-- 1. Transition function: adds natural log of value to running sum and count
CREATE OR REPLACE FUNCTION geo_mean_state(state NUMERIC[], val NUMERIC)
RETURNS NUMERIC[] AS $$
BEGIN
    IF val > 0 THEN
        RETURN ARRAY[state[1] + LN(val), state[2] + 1];
    END IF;
    RETURN state;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 2. Final function: computes EXP(sum_ln / count)
CREATE OR REPLACE FUNCTION geo_mean_final(state NUMERIC[])
RETURNS NUMERIC AS $$
BEGIN
    IF state[2] > 0 THEN
        RETURN EXP(state[1] / state[2]);
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 3. Define the Aggregate
CREATE AGGREGATE geometric_mean (NUMERIC) (
    SFUNC = geo_mean_state,
    STYPE = NUMERIC[],
    FINALFUNC = geo_mean_final,
    INITCOND = '{0, 0}'
);

CREATE OR REPLACE FUNCTION geo_mean_sfunc(
    state double precision,
    value double precision
)
RETURNS double precision
LANGUAGE sql
AS $$
    SELECT state + ln(value);
$$;

CREATE OR REPLACE FUNCTION geo_mean_final(
    state double precision
)
RETURNS double precision
LANGUAGE sql
AS $$
    SELECT exp(state);
$$;

CREATE AGGREGATE geo_mean (double precision) (
    SFUNC    = geo_mean_sfunc,
    STYPE    = double precision,
    FINALFUNC = geo_mean_final,
    INITCOND = '0'
);

SELECT geo_mean(growth_rate) FROM metrics;
